package net.spell_engine.internals;
import java.util.*;import com.google.gson.*;import net.minecraft.resources.Identifier;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.effect.MobEffects;import net.spell_engine.api.spell.fx.*;import net.spell_engine.fx.*;import net.spell_engine.api.effect.GlowingItemStatusEffect;
/** Presentation only. Uses the existing received-details update; no new listener or gameplay clock. */
public final class ClassStatusVisuals {
 public record Cue(String id,long color,boolean ownerOnly,boolean shield){}
 static final Map<String,Long> COLORS=new LinkedHashMap<>();static final Set<String> ROGUE=new HashSet<>(),SHIELDS=Set.of("skill_tree_rpgs:priest_penance_shield","skill_tree_rpgs:priest_serenity_shield","skill_tree_rpgs:tenacity_ward","skill_tree_rpgs:arcane_ward","skill_tree_rpgs:fire_ward","skill_tree_rpgs:frost_ward");
 static void group(long color,String...ids){for(String id:ids)COLORS.put(id.contains(":")?id:"skill_tree_rpgs:"+id,color);}
 static{group(0xDFA7F0FFL,"rogues:slice_and_dice","opportunist","side_step","cheat_death_evasion","slice_evasion","prepared_counter_ready");ROGUE.addAll(COLORS.keySet());group(0xE5B752FFL,"rhythm","supercharge","deflection","archers:hunters_mark_stash");group(0xD79062FFL,"killing_spree","vitality","concussion_blow","warrior_momentum_ready","warrior_momentum","warrior_freedom","warrior_endurance","sentinel","enrage","tenacity_ward");group(0xEAE6A8FFL,"healing_focus","incanter_cadence","ascension_power","divine_favor","pain_suppression","celestial_orb","priest_penance_shield","priest_serenity_shield");group(0xB99EF4FFL,"wizards:arcane_charge","wizards:arcane_evocation","arcane_exposure","arcane_vulnerability","presence_of_mind","arcane_ward");group(0xEE883CFFL,"fire_vulnerability","blazing_speed","fire_ward");group(0xA9DFFFFFL,"frost_vulnerability","arctic_reflex","frost_ward");group(0xBAA17DFFL,"fracture");}
 public static boolean concealed(LivingEntity e){return e.isInvisible()||e.hasEffect(MobEffects.INVISIBILITY)||e.getActiveEffects().stream().anyMatch(f->f.getEffect().is(Identifier.parse("rogues:stealth"))||f.getEffect().is(Identifier.parse("skill_tree_rpgs:priest_fade")));}
 public static List<Cue> gains(Map<String,Integer> before,Map<String,Integer> current,boolean hidden,float oldAbsorption,float absorption){var result=new ArrayList<Cue>();boolean shieldShown=false;for(var row:current.entrySet()){String key=row.getKey();boolean owner=ROGUE.contains(key),shield=SHIELDS.contains(key);if(!COLORS.containsKey(key)||(hidden&&!owner))continue;boolean gain=shield?absorption>oldAbsorption+.001:row.getValue()>before.getOrDefault(key,0);if(gain&&(!shield||!shieldShown)){result.add(new Cue(key,COLORS.get(key),owner,shield));if(shield)shieldShown=true;}}return result;}
 public static void update(LivingEntity e){if(e.level().isClientSide())return;var root=EffectDetails.data(e);var previous=EffectDetails.object(root,"class_visual_snapshot");var before=new HashMap<String,Integer>();for(var row:previous.entrySet())if(!row.getKey().equals("absorption"))before.put(row.getKey(),row.getValue().getAsInt());var current=new LinkedHashMap<String,Integer>();for(var f:e.isAlive()?e.getActiveEffects():List.<net.minecraft.world.effect.MobEffectInstance>of()){String id=f.getEffect().getRegisteredName();if(COLORS.containsKey(id))current.put(id,f.getAmplifier()+1);}for(var cue:gains(before,current,concealed(e), (float)EffectDetails.number(previous,"absorption"),e.getAbsorptionAmount()))emit(e,cue);var next=new JsonObject();current.forEach(next::addProperty);next.addProperty("absorption",e.getAbsorptionAmount());if(!next.equals(previous)){root.add("class_visual_snapshot",next);EffectDetails.save(e,root);}}
 static void emit(LivingEntity e,Cue cue){var group=ParticleGroupBuilder.magic(SpellEngineParticles.magic_spark,ParticleGroup.Motion.ASCEND).color(cue.color).scale(cue.shield?.32f:.22f).batch(b->b.shape(cue.shield?ParticleGroup.Shape.PIPE:ParticleGroup.Shape.SPHERE).count(cue.shield?6:3).speed(.025f,.07f));if(cue.ownerOnly){if(e instanceof ServerPlayer p)ParticleHelper.sendBatches(e,List.of(group),1,List.of(p));}else ParticleHelper.sendBatches(e,List.of(group));}
 public static void configure(){for(var row:Map.of("skill_tree_rpgs:supercharge",0xE5B752,"skill_tree_rpgs:prepared_counter_ready",0xC493E5,"skill_tree_rpgs:concussion_blow",0xDEAB72,"skill_tree_rpgs:divine_favor",0xF5E4AE,"skill_tree_rpgs:presence_of_mind",0xBD98EC,"skill_tree_rpgs:arctic_reflex",0x9CDCEC).entrySet()){var effect=net.skill_tree_rpgs.effect.SkillEffects.entries.stream().filter(f->f.id.toString().equals(row.getKey())).findFirst();if(effect.isPresent()){int c=row.getValue();GlowingItemStatusEffect.register(effect.get().effect,new net.spell_engine.client.util.Color(((c>>16)&255)/255f,((c>>8)&255)/255f,(c&255)/255f),.3f);}}}
}
